contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test Deposit: given an amount `amount`, calling c.Deposit{value: amount} should either revert
    // or increase both the contract's recorded balance for this contract and the c contract's
    // Ether balance by exactly amount.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read before values
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        bool reverted;
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General rule: if the call reverted then nothing observable changed; otherwise
        // the recorded balance and contract balance each increased by exactly amount.
        assert(
            reverted
            ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            : (afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount)
        );
    }

    receive() external payable {}
}

