// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(reverted
            ? (afterRecorded == beforeRecorded && afterContractBal == beforeContractBal)
            : (afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
